const fluvalLogo = "data:image/png;base64,";
/* Fluval Connect aquarium controls. No external dependencies or automatic writes. */
const fluvalEscape = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
